-- Transactions cell (transactions), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA transactions;

CREATE FUNCTION transactions.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE transactions.transactions (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    transaction_date         date NOT NULL,
    transaction_type         text NOT NULL CHECK (transaction_type IN ('income', 'expense', 'transfer', 'refund', 'fee', 'adjustment')),
    amount                   double precision NOT NULL CHECK (amount >= 0),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    account_id               bigint,
    owner_scope              text NOT NULL DEFAULT 'personal' CHECK (owner_scope IN ('personal', 'solo_empire', 'venture', 'client', 'shared')),
    category                 text,
    merchant                 text,
    description              text,
    source                   text NOT NULL DEFAULT 'manual',
    subscription_id          bigint,
    metadata                 jsonb CHECK (metadata IS NULL OR (jsonb_typeof(metadata) = 'object')),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX transactions_legacy ON transactions.transactions (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX transactions_account_id ON transactions.transactions (workspace_id, account_id);
CREATE INDEX transactions_category ON transactions.transactions (workspace_id, category);
CREATE INDEX transactions_owner_scope ON transactions.transactions (workspace_id, owner_scope);
CREATE INDEX transactions_transaction_type ON transactions.transactions (workspace_id, transaction_type);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE transactions.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('transaction')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE transactions.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON transactions.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['transactions', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE transactions.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE transactions.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON transactions.%I'
                       ' USING (workspace_id = transactions.current_workspace())'
                       ' WITH CHECK (workspace_id = transactions.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA transactions TO transactions_api;
GRANT EXECUTE ON FUNCTION transactions.current_workspace() TO transactions_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON transactions.transactions TO transactions_api;
GRANT USAGE ON SEQUENCE transactions.transactions_id_seq TO transactions_api;
GRANT SELECT, INSERT ON transactions.create_keys TO transactions_api;
GRANT SELECT, INSERT ON transactions.outbox TO transactions_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON transactions.outbox TO transactions_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON transactions.outbox TO transactions_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA transactions TO transactions_publisher;
GRANT SELECT ON transactions.outbox TO transactions_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON transactions.outbox TO transactions_publisher;
